//! WebAssembly bindings of the Hexa engine (SCR-07, NFR-13).
//!
//! The JavaScript API, generated by `wasm-bindgen`:
//!
//! * [`HexDocument`] — an in-memory editable buffer on the `hexa-core` piece
//!   tree: `fromBytes`, `length`, `read`, `overwrite`, `insert`, `delete`,
//!   `replace`, `undo` / `redo`, `toBytes`, `search`, `hash`.
//! * [`search`] — hex (with `??` wildcards), text and regex search returning
//!   match offsets.
//! * [`hash`] / [`hash_algorithms`] — checksums, CRCs, cryptographic, fast
//!   and fuzzy hashes (`hexa-core` + `hexa-analysis`).
//! * [`diff`] — binary diff regions and statistics (`hexa-diff`).
//! * [`create_patch`] / [`apply_patch`] — IPS, UPS, BPS, VCDIFF, bsdiff.
//! * [`transform`] — a `hexa-transform` recipe (JSON) applied to bytes.
//! * [`entropy`] — Shannon entropy in bits per byte.
//!
//! Offsets and lengths are JavaScript numbers (safe up to 2^53). Errors are
//! thrown as JavaScript `Error`s. Every function has a plain Rust
//! counterpart used by the native unit tests (the `*_impl` functions and the
//! inherent methods), so `cargo test -p hexa-wasm` runs on the host.

use hexa_core::search::{Query, Scope, compile, find_all};
use hexa_core::{Cancel, Document, Tree};
use hexa_diff::{DiffMode, DiffOptions, PatchFormat};
use serde::{Deserialize, Serialize};
use wasm_bindgen::prelude::*;

#[wasm_bindgen(typescript_custom_section)]
const TS_TYPES: &str = r#"
/** Options of `search` / `HexDocument.search`. */
export interface SearchOptions {
  /** Text encodings, default `["utf-8"]` (`utf-16le`, `latin1`, …). */
  encodings?: string[];
  /** Default `true`. */
  caseSensitive?: boolean;
  /** Regex over UTF-8 text instead of raw bytes. */
  unicode?: boolean;
  /** Maximum number of matches, default 100000. */
  max?: number;
  /** Only report offsets that are multiples of this. */
  align?: number;
}

/** One hash result; `value` is lower-case hex (CRCs upper-case). */
export interface HashValue { id: string; value: string; }

/** A hash algorithm. */
export interface AlgoInfo { id: string; name: string; group: string; }

/** Options of `diff`. */
export interface DiffOptions {
  /** Compare offset by offset (no insert/delete detection). */
  bytewise?: boolean;
  /** Also report equal regions. */
  includeEqual?: boolean;
  /** Merge differences separated by fewer equal bytes than this. */
  mergeGap?: number;
}

export interface Span { start: number; len: number; }
export interface DiffRegion {
  a: Span;
  b: Span;
  kind: "equal" | "changed" | "inserted" | "deleted";
}
export interface KindStats { count: number; bytesA: number; bytesB: number; }
export interface DiffStats {
  lenA: number;
  lenB: number;
  equalBytes: number;
  matchPercent: number;
  equal: KindStats;
  changed: KindStats;
  inserted: KindStats;
  deleted: KindStats;
  differences: number;
}
export interface DiffResult { regions: DiffRegion[]; stats: DiffStats; truncated: boolean; }
"#;

/// Default cap on reported search matches.
const DEFAULT_MAX_MATCHES: usize = 100_000;

/// An error surfaced to JavaScript as an `Error`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HexaError(pub String);

impl HexaError {
    fn new(msg: impl Into<String>) -> Self {
        Self(msg.into())
    }
}

impl std::fmt::Display for HexaError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl From<HexaError> for JsValue {
    fn from(e: HexaError) -> Self {
        js_sys::Error::new(&e.0).into()
    }
}

impl From<hexa_core::Error> for HexaError {
    fn from(e: hexa_core::Error) -> Self {
        Self(e.to_string())
    }
}

impl From<std::io::Error> for HexaError {
    fn from(e: std::io::Error) -> Self {
        Self(e.to_string())
    }
}

impl From<hexa_transform::TransformError> for HexaError {
    fn from(e: hexa_transform::TransformError) -> Self {
        Self(e.to_string())
    }
}

impl From<serde_wasm_bindgen::Error> for HexaError {
    fn from(e: serde_wasm_bindgen::Error) -> Self {
        Self(e.to_string())
    }
}

pub type Result<T, E = HexaError> = std::result::Result<T, E>;

/// Converts a JavaScript number to an offset / length.
fn to_u64(v: f64, what: &str) -> Result<u64> {
    if v.is_finite() && v >= 0.0 && v.fract() == 0.0 && v <= 9_007_199_254_740_991.0 {
        Ok(v as u64)
    } else {
        Err(HexaError::new(format!(
            "{what} must be a non-negative integer, got {v}"
        )))
    }
}

fn to_js<T: Serialize + ?Sized>(v: &T) -> Result<JsValue> {
    let ser = serde_wasm_bindgen::Serializer::json_compatible();
    Ok(v.serialize(&ser)?)
}

fn tree_of(bytes: &[u8]) -> Tree {
    Document::from_bytes("bytes", bytes.to_vec()).snapshot()
}

fn no_progress(_: u64, _: u64) {}

fn tree_vec(tree: &Tree) -> Result<Vec<u8>> {
    let len = usize::try_from(tree.len()).map_err(|_| HexaError::new("data too large"))?;
    Ok(tree.read_vec(0, len)?)
}

// ---------------------------------------------------------------------------
// HexDocument
// ---------------------------------------------------------------------------

/// An editable in-memory buffer with undo / redo.
#[wasm_bindgen]
#[derive(Debug)]
pub struct HexDocument {
    doc: Document,
}

impl Default for HexDocument {
    fn default() -> Self {
        Self::new()
    }
}

#[wasm_bindgen]
impl HexDocument {
    /// An empty document.
    #[wasm_bindgen(constructor)]
    pub fn new() -> Self {
        Self::from_bytes(&[])
    }

    /// A document holding a copy of `bytes`.
    #[wasm_bindgen(js_name = fromBytes)]
    pub fn from_bytes(bytes: &[u8]) -> Self {
        let mut doc = Document::from_bytes("Untitled", bytes.to_vec());
        // Overwrite is the default; insert/delete stay allowed.
        doc.set_fixed_size(false);
        Self { doc }
    }

    /// Length in bytes.
    #[wasm_bindgen(getter)]
    pub fn length(&self) -> f64 {
        self.doc.len() as f64
    }

    /// Length in bytes (same as `length`).
    pub fn len(&self) -> f64 {
        self.length()
    }

    /// `true` when the document holds no bytes.
    #[wasm_bindgen(js_name = isEmpty)]
    pub fn is_empty(&self) -> bool {
        self.doc.is_empty()
    }

    /// Reads up to `length` bytes at `offset` (fewer at the end).
    pub fn read(&self, offset: f64, length: f64) -> Result<Vec<u8>> {
        let offset = to_u64(offset, "offset")?;
        let length = to_u64(length, "length")?;
        let len = self.doc.len();
        if offset > len {
            return Err(HexaError::new(format!(
                "offset {offset} is beyond the end ({len})"
            )));
        }
        let n = length.min(len - offset);
        Ok(self.doc.read_vec(offset, n as usize)?)
    }

    /// Overwrites bytes at `offset` (may extend the document at its end).
    pub fn overwrite(&mut self, offset: f64, bytes: &[u8]) -> Result<()> {
        self.doc.overwrite(to_u64(offset, "offset")?, bytes)?;
        Ok(())
    }

    /// Inserts bytes at `offset`.
    pub fn insert(&mut self, offset: f64, bytes: &[u8]) -> Result<()> {
        self.doc.insert(to_u64(offset, "offset")?, bytes)?;
        Ok(())
    }

    /// Deletes `length` bytes at `offset`.
    pub fn delete(&mut self, offset: f64, length: f64) -> Result<()> {
        let start = to_u64(offset, "offset")?;
        let end = start.saturating_add(to_u64(length, "length")?);
        self.doc.delete(start, end)?;
        Ok(())
    }

    /// Replaces `length` bytes at `offset` with `bytes`.
    pub fn replace(&mut self, offset: f64, length: f64, bytes: &[u8]) -> Result<()> {
        let start = to_u64(offset, "offset")?;
        let end = start.saturating_add(to_u64(length, "length")?);
        self.doc.replace(start, end, bytes)?;
        Ok(())
    }

    /// Undoes the last edit; `false` when there is nothing to undo.
    pub fn undo(&mut self) -> bool {
        self.doc.undo().is_some()
    }

    /// Redoes the last undone edit; `false` when there is nothing to redo.
    pub fn redo(&mut self) -> bool {
        self.doc.redo().is_some()
    }

    #[wasm_bindgen(getter, js_name = canUndo)]
    pub fn can_undo(&self) -> bool {
        self.doc.can_undo()
    }

    #[wasm_bindgen(getter, js_name = canRedo)]
    pub fn can_redo(&self) -> bool {
        self.doc.can_redo()
    }

    /// Whether the content differs from the initial bytes' history state.
    #[wasm_bindgen(getter, js_name = isModified)]
    pub fn is_modified(&self) -> bool {
        self.doc.is_modified()
    }

    /// A copy of the whole content.
    #[wasm_bindgen(js_name = toBytes)]
    pub fn to_bytes(&self) -> Result<Vec<u8>> {
        tree_vec(&self.doc.snapshot())
    }

    /// Searches the document; see the free [`search`] function.
    #[wasm_bindgen(js_name = search)]
    pub fn search_js(
        &self,
        kind: &str,
        pattern: &str,
        #[wasm_bindgen(unchecked_optional_param_type = "SearchOptions")] options: Option<
            js_sys::Object,
        >,
    ) -> Result<Vec<f64>> {
        let opts = SearchOptions::from_js(options)?;
        self.search(kind, pattern, &opts)
    }

    /// Hashes the document; see the free [`hash`] function.
    #[wasm_bindgen(js_name = hash, unchecked_return_type = "HashValue[]")]
    #[allow(
        clippy::needless_pass_by_value,
        reason = "wasm-bindgen needs an owned string array"
    )]
    pub fn hash_js(&self, ids: Vec<String>) -> Result<JsValue> {
        to_js(&hash_tree(&self.doc.snapshot(), &ids)?)
    }
}

impl HexDocument {
    /// Rust counterpart of `search`.
    pub fn search(&self, kind: &str, pattern: &str, opts: &SearchOptions) -> Result<Vec<f64>> {
        search_tree(&self.doc.snapshot(), kind, pattern, opts)
    }

    /// Rust counterpart of `hash`.
    pub fn hash(&self, ids: &[String]) -> Result<Vec<HashValue>> {
        hash_tree(&self.doc.snapshot(), ids)
    }
}

// ---------------------------------------------------------------------------
// Search
// ---------------------------------------------------------------------------

/// Options of [`search`] (all optional on the JavaScript side).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct SearchOptions {
    /// Text encodings (`utf-8`, `utf-16le`, `latin1` …).
    pub encodings: Vec<String>,
    pub case_sensitive: bool,
    /// Regex over UTF-8 text instead of raw bytes.
    pub unicode: bool,
    /// Maximum number of matches.
    pub max: usize,
    /// Only report offsets that are multiples of this.
    pub align: u64,
}

impl Default for SearchOptions {
    fn default() -> Self {
        Self {
            encodings: vec!["utf-8".into()],
            case_sensitive: true,
            unicode: false,
            max: DEFAULT_MAX_MATCHES,
            align: 1,
        }
    }
}

impl SearchOptions {
    fn from_js(v: Option<js_sys::Object>) -> Result<Self> {
        match v {
            None => Ok(Self::default()),
            Some(o) => Ok(serde_wasm_bindgen::from_value(o.into())?),
        }
    }
}

fn search_tree(tree: &Tree, kind: &str, pattern: &str, o: &SearchOptions) -> Result<Vec<f64>> {
    let q = match kind {
        "hex" => Query::Hex {
            pattern: pattern.into(),
        },
        "text" => Query::Text {
            text: pattern.into(),
            encodings: o.encodings.clone(),
            case_sensitive: o.case_sensitive,
        },
        "regex" => Query::Regex {
            pattern: pattern.into(),
            unicode: o.unicode,
        },
        other => {
            return Err(HexaError::new(format!(
                "unknown search kind `{other}` (hex, text or regex)"
            )));
        }
    };
    let matcher = compile(&q)?;
    let scope = Scope {
        align: o.align.max(1),
        ..Scope::whole(tree)
    };
    let mut out = Vec::new();
    find_all(
        tree,
        &matcher,
        scope,
        o.max.max(1),
        &Cancel::new(),
        &no_progress,
        |m| out.push(m.offset as f64),
    )?;
    Ok(out)
}

/// Finds `pattern` in `bytes`; returns the match offsets.
///
/// `kind` is `"hex"` (`"DE AD ?? EF"`), `"text"` or `"regex"`; `options` is
/// `{ encodings?, caseSensitive?, unicode?, max?, align? }`.
#[wasm_bindgen(js_name = search)]
pub fn search_js(
    bytes: &[u8],
    kind: &str,
    pattern: &str,
    #[wasm_bindgen(unchecked_optional_param_type = "SearchOptions")] options: Option<
        js_sys::Object,
    >,
) -> Result<Vec<f64>> {
    search(bytes, kind, pattern, &SearchOptions::from_js(options)?)
}

/// Rust counterpart of the JavaScript `search`.
pub fn search(bytes: &[u8], kind: &str, pattern: &str, opts: &SearchOptions) -> Result<Vec<f64>> {
    search_tree(&tree_of(bytes), kind, pattern, opts)
}

// ---------------------------------------------------------------------------
// Hashes
// ---------------------------------------------------------------------------

/// One hash result.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct HashValue {
    pub id: String,
    pub value: String,
}

fn hash_tree(tree: &Tree, ids: &[String]) -> Result<Vec<HashValue>> {
    let res = hexa_analysis::hash::hash_range(
        tree,
        0,
        tree.len(),
        ids,
        None,
        &Cancel::new(),
        &no_progress,
    )?;
    Ok(res
        .into_iter()
        .map(|r| HashValue {
            id: r.id,
            value: r.value,
        })
        .collect())
}

/// Hashes `bytes` with every algorithm in `ids` (`sha256`, `md5`,
/// `crc:CRC-32/ISO-HDLC`, `xxh64`, `ssdeep` … see `hashAlgorithms()`);
/// returns `[{ id, value }]` with lower-case hex values.
#[wasm_bindgen(js_name = hash, unchecked_return_type = "HashValue[]")]
#[allow(
    clippy::needless_pass_by_value,
    reason = "wasm-bindgen needs an owned string array"
)]
pub fn hash_js(bytes: &[u8], ids: Vec<String>) -> Result<JsValue> {
    to_js(&hash(bytes, &ids)?)
}

/// Rust counterpart of the JavaScript `hash`.
pub fn hash(bytes: &[u8], ids: &[String]) -> Result<Vec<HashValue>> {
    hash_tree(&tree_of(bytes), ids)
}

/// Every available hash algorithm as `[{ id, name, group }]`.
#[wasm_bindgen(js_name = hashAlgorithms, unchecked_return_type = "AlgoInfo[]")]
pub fn hash_algorithms_js() -> Result<JsValue> {
    to_js(&hash_algorithms())
}

/// Rust counterpart of `hashAlgorithms`.
pub fn hash_algorithms() -> Vec<hexa_core::hash::AlgoInfo> {
    let mut v = hexa_core::hash::algorithms();
    v.extend(hexa_analysis::hash::algorithms());
    v
}

/// Shannon entropy of `bytes` in bits per byte (0…8).
pub fn entropy(bytes: &[u8]) -> f64 {
    hexa_analysis::stats::entropy(bytes)
}

/// `entropy` exported under its JavaScript name.
#[wasm_bindgen(js_name = entropy)]
pub fn entropy_js(bytes: &[u8]) -> f64 {
    entropy(bytes)
}

// ---------------------------------------------------------------------------
// Diff and patches
// ---------------------------------------------------------------------------

/// Options of [`diff`].
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct DiffOpts {
    /// Compare offset by offset (no insert/delete detection).
    pub bytewise: bool,
    /// Also report equal regions.
    pub include_equal: bool,
    /// Merge differences separated by fewer equal bytes than this.
    pub merge_gap: u64,
}

/// Compares two buffers; returns `{ regions, stats, truncated }` where a
/// region is `{ a: {start, len}, b: {start, len}, kind }` and `kind` is
/// `changed`, `inserted`, `deleted` or `equal`. `options` is
/// `{ bytewise?, includeEqual?, mergeGap? }`.
#[wasm_bindgen(js_name = diff, unchecked_return_type = "DiffResult")]
pub fn diff_js(
    a: &[u8],
    b: &[u8],
    #[wasm_bindgen(unchecked_optional_param_type = "DiffOptions")] options: Option<js_sys::Object>,
) -> Result<JsValue> {
    let opts = match options {
        None => DiffOpts::default(),
        Some(o) => serde_wasm_bindgen::from_value(o.into())?,
    };
    to_js(&diff(a, b, &opts)?)
}

/// Rust counterpart of the JavaScript `diff`.
pub fn diff(a: &[u8], b: &[u8], o: &DiffOpts) -> Result<hexa_diff::DiffResult> {
    let opts = DiffOptions {
        mode: if o.bytewise {
            DiffMode::Bytewise
        } else {
            DiffMode::ShiftAware
        },
        include_equal: o.include_equal,
        merge_gap: o.merge_gap,
        ..DiffOptions::default()
    };
    Ok(hexa_diff::diff(
        &tree_of(a),
        &tree_of(b),
        &opts,
        &Cancel::new(),
        &no_progress,
    )?)
}

fn patch_format(name: &str) -> Result<PatchFormat> {
    PatchFormat::ALL
        .into_iter()
        .find(|f| {
            f.extension() == name || serde_json::to_value(f).ok().as_ref() == Some(&name.into())
        })
        .ok_or_else(|| {
            HexaError::new(format!(
                "unknown patch format `{name}` (ips, ups, bps, vcdiff, bsdiff)"
            ))
        })
}

/// Creates a patch (`"ips"`, `"ups"`, `"bps"`, `"vcdiff"`, `"bsdiff"`)
/// turning `source` into `target`.
#[wasm_bindgen(js_name = createPatch)]
pub fn create_patch(format: &str, source: &[u8], target: &[u8]) -> Result<Vec<u8>> {
    Ok(hexa_diff::create_patch(
        patch_format(format)?,
        &tree_of(source),
        &tree_of(target),
        &hexa_diff::CreateOptions::default(),
        &Cancel::new(),
        &no_progress,
    )?)
}

/// Applies a patch (format detected from its magic) to `source`.
#[wasm_bindgen(js_name = applyPatch)]
pub fn apply_patch(source: &[u8], patch: &[u8]) -> Result<Vec<u8>> {
    let applied = hexa_diff::apply_patch(
        None,
        patch,
        &tree_of(source),
        &hexa_diff::ApplyOptions::default(),
        &Cancel::new(),
        &no_progress,
    )?;
    tree_vec(&applied.target)
}

// ---------------------------------------------------------------------------
// Transformations
// ---------------------------------------------------------------------------

/// Applies a `hexa-transform` recipe to `bytes`. `recipe` is JSON: either
/// `{"steps":[…]}` or a bare step array, e.g.
/// `[{"kind":"bitwise","op":"xor","operand":"0xFF"}]`.
#[wasm_bindgen(js_name = transform)]
pub fn transform(bytes: &[u8], recipe: &str) -> Result<Vec<u8>> {
    let recipe = if recipe.trim_start().starts_with('[') {
        hexa_transform::Recipe::new(
            serde_json::from_str(recipe).map_err(|e| HexaError::new(format!("recipe: {e}")))?,
        )
    } else {
        hexa_transform::Recipe::from_json(recipe)?
    };
    recipe.validate()?;
    Ok(hexa_transform::apply(&recipe, bytes)?)
}

/// Version of the engine.
#[wasm_bindgen]
pub fn version() -> String {
    env!("CARGO_PKG_VERSION").into()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ids(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| (*s).to_owned()).collect()
    }

    #[test]
    fn document_edits_and_history() {
        let mut d = HexDocument::from_bytes(b"hello world");
        assert!((d.len() - 11.0).abs() < f64::EPSILON);
        assert_eq!(d.read(6.0, 100.0).unwrap(), b"world");
        d.overwrite(0.0, b"J").unwrap();
        d.insert(5.0, b",").unwrap();
        d.delete(6.0, 1.0).unwrap();
        assert_eq!(d.to_bytes().unwrap(), b"Jello,world");
        d.replace(6.0, 5.0, b"there!").unwrap();
        assert_eq!(d.to_bytes().unwrap(), b"Jello,there!");
        assert!(d.is_modified());
        assert!(d.undo());
        assert_eq!(d.to_bytes().unwrap(), b"Jello,world");
        assert!(d.can_redo());
        assert!(d.redo());
        assert_eq!(d.to_bytes().unwrap(), b"Jello,there!");
        while d.undo() {}
        assert_eq!(d.to_bytes().unwrap(), b"hello world");
        assert!(!d.can_undo());
        assert!(d.read(-1.0, 1.0).is_err());
        assert!(d.read(1.5, 1.0).is_err());
        assert!(d.read(12.0, 1.0).is_err());
        assert!(d.delete(10.0, 5.0).is_err());
    }

    #[test]
    fn empty_document_grows() {
        let mut d = HexDocument::new();
        assert!(d.is_empty());
        d.insert(0.0, b"abc").unwrap();
        d.overwrite(3.0, b"de").unwrap();
        assert_eq!(d.to_bytes().unwrap(), b"abcde");
    }

    #[test]
    fn searching() {
        let data = b"xxABCDxxabcdxxAB\x00C\x00";
        let opts = SearchOptions::default();
        assert_eq!(search(data, "hex", "41 42 ?? 44", &opts).unwrap(), [2.0]);
        let ci = SearchOptions {
            case_sensitive: false,
            ..SearchOptions::default()
        };
        assert_eq!(search(data, "text", "abcd", &ci).unwrap(), [2.0, 8.0]);
        let utf16 = SearchOptions {
            encodings: vec!["utf-16le".into()],
            ..SearchOptions::default()
        };
        assert_eq!(search(data, "text", "BC", &utf16).unwrap(), [15.0]);
        assert_eq!(search(data, "regex", "[a-d]{4}", &opts).unwrap(), [8.0]);
        let max1 = SearchOptions { max: 1, ..ci };
        assert_eq!(search(data, "text", "abcd", &max1).unwrap(), [2.0]);
        assert!(search(data, "hex", "4G", &opts).is_err());
        assert!(search(data, "nope", "x", &opts).is_err());
        let d = HexDocument::from_bytes(data);
        assert_eq!(d.search("hex", "78 78", &opts).unwrap().len(), 3);
    }

    #[test]
    fn hashing() {
        let r = hash(
            b"123456789",
            &ids(&["crc:CRC-32/ISO-HDLC", "sha256", "xxh32"]),
        )
        .unwrap();
        assert_eq!(r[0].value.to_ascii_lowercase(), "cbf43926");
        assert_eq!(
            r[1].value,
            "15e2b0d3c33891ebb0f1ef609ec419420c20e320ce94c65fbc8c3312448eb225"
        );
        assert_eq!(r[2].id, "xxh32");
        assert!(hash(b"x", &ids(&["nope"])).is_err());
        assert!(hash_algorithms().iter().any(|a| a.id == "ssdeep"));
        let d = HexDocument::from_bytes(b"abc");
        assert_eq!(
            d.hash(&ids(&["sha1"])).unwrap()[0].value,
            "a9993e364706816aba3e25717850c26c9cd0d89d"
        );
        assert!(entropy(&[0, 1, 2, 3]) > 1.99);
    }

    #[test]
    fn diffing_and_patches() {
        let a = b"the quick brown fox".to_vec();
        let b = b"the quick red fox!".to_vec();
        let r = diff(&a, &b, &DiffOpts::default()).unwrap();
        assert!(r.stats.differences > 0);
        let json = serde_json::to_value(&r).unwrap();
        assert!(json["regions"][0]["kind"].is_string());
        let same = diff(&a, &a, &DiffOpts::default()).unwrap();
        assert_eq!(same.regions, []);
        for f in ["ips", "ups", "bps", "vcdiff", "bsdiff"] {
            let p = create_patch(f, &a, &b).unwrap();
            assert_eq!(apply_patch(&a, &p).unwrap(), b, "{f}");
        }
        assert!(create_patch("zip", &a, &b).is_err());
        assert!(apply_patch(&a, b"junk").is_err());
    }

    #[test]
    fn transforms() {
        let out = transform(
            b"hello",
            r#"[{"kind":"bitwise","op":"xor","operand":"0x20"}]"#,
        )
        .unwrap();
        assert_eq!(out, b"HELLO");
        let out = transform(b"hi", r#"{"steps":[{"kind":"not"}]}"#).unwrap();
        assert_eq!(out, [!b'h', !b'i']);
        assert!(transform(b"x", r#"{"steps":[{"kind":"nope"}]}"#).is_err());
        assert_eq!(version(), env!("CARGO_PKG_VERSION"));
    }
}
